type UpdateApprovalPolicyParams struct {
	MinApprovals      int64
	AllowSelfApproval int64
	RequestTtlSeconds int64
	Enabled           int64
	UpdatedAt         string
	OrgID             string
	ProjectID         string
	ID                string
}

// UpdateApprovalPolicy bumps version so any request pinned to the older version
// fails closed. The service invalidates open requests to the covered
// environment in the same transaction.
func (q *Queries) UpdateApprovalPolicy(ctx context.Context, arg UpdateApprovalPolicyParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateApprovalPolicy,
		arg.MinApprovals,
		arg.AllowSelfApproval,
		arg.RequestTtlSeconds,
		arg.Enabled,
		arg.UpdatedAt,
		arg.OrgID,
		arg.ProjectID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateApprovalRequestState = `-- name: UpdateApprovalRequestState :execrows
UPDATE approval_requests
SET state = ?, invalidated_cause = ?, resolved_at = ?
WHERE org_id = ? AND project_id = ? AND environment_id = ? AND id = ?
`

type UpdateApprovalRequestStateParams struct {
	State            string
	InvalidatedCause string
	ResolvedAt       sql.NullString
	OrgID            string
	ProjectID        string
	EnvironmentID    string
	ID               string
}

// UpdateApprovalRequestState transitions one request. resolved_at is NULL for
// the approved state and set for every terminal state; invalidated_cause is ”
// unless the terminal state is invalidated.
func (q *Queries) UpdateApprovalRequestState(ctx context.Context, arg UpdateApprovalRequestStateParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateApprovalRequestState,
		arg.State,
		arg.InvalidatedCause,
		arg.ResolvedAt,
		arg.OrgID,
		arg.ProjectID,
		arg.EnvironmentID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
